const targetOrigin = process.env.ADDIN_URL;

/**
 * Shows a notification when the add-in command is executed.
 * @param event
 */
function action(event: Office.AddinCommands.Event) {
  const message: Office.NotificationMessageDetails = {
    type: Office.MailboxEnums.ItemNotificationMessageType.InformationalMessage,
    message: "Performed action.",
    icon: "Icon.80x80",
    persistent: true,
  };

  // Show a notification message.
  Office.context.mailbox.item?.notificationMessages.replaceAsync(
    "ActionPerformanceNotification",
    message
  );

  // Be sure to indicate when the add-in command function is complete.
  event.completed();
}

type SafeRecipientsChangedEvent = Office.RecipientsChangedEventArgs &
  Office.MailboxEvent & {
    to?: boolean;
    cc?: boolean;
    bcc?: boolean;
  };

interface ExternalRecipientsValidationResult {
  HasExternalDomain: boolean;
  ExternalRecipients: string[];
}


/**
 * Shared logic to inspect fields, check for external domains, and update the Outlook UI.
 */
async function validateRecipientsAndShowNotification(mailItem: Office.MessageCompose, checkTo: boolean, checkCc: boolean, checkBcc: boolean): Promise<void> {
  //const targetDomain = "@inMailX.onmicrosoft.com";
  let hasExternalRecipient = false;

  try {
    const itemHasAttachments = await selectedItemHasAttachments().catch(() => false);

    // FIXED: Run lookups sequentially to avoid overloading the Outlook background thread during multi-field updates.
    // Early exit condition ensures we drop field evaluation if an external user was already identified.
    if (checkTo && mailItem.to) {
      const toRecipients = await getRecipientsWithTimeout(mailItem.to).catch(() => []);
      if (hasInvalidDomain(toRecipients)) {
        hasExternalRecipient = true;
      }
    }

    if (!hasExternalRecipient && checkCc && mailItem.cc) {
      const ccRecipients = await getRecipientsWithTimeout(mailItem.cc).catch(() => []);
      if (hasInvalidDomain(ccRecipients)) {
        hasExternalRecipient = true;
      }
    }

    if (!hasExternalRecipient && checkBcc && mailItem.bcc) {
      const bccRecipients = await getRecipientsWithTimeout(mailItem.bcc).catch(() => []);
      if (hasInvalidDomain(bccRecipients)) {
        hasExternalRecipient = true;
      }
    }

    // Update the Outlook notification UI securely using awaited Promises
    if (hasExternalRecipient) {
      // const isMobile = Office.context.diagnostics.platform === Office.PlatformType.Android ||
      //   Office.context.diagnostics.platform === Office.PlatformType.iOS;

      const warningWithAttachments = "Warning: Verify that each recipient and attachment is correct before sending.";
      const warningWithoutAttachments = "Warning: Verify that each recipient is correct before sending.";

      const isAndroidMobile =
        Office.context.diagnostics.platform === Office.PlatformType.Android ||
        /Android/i.test(navigator.userAgent);

      const isiOSMobile =
        Office.context.diagnostics.platform === Office.PlatformType.iOS ||
        /iPhone|iPad|iPod/i.test(navigator.userAgent);

      const isMobile = isAndroidMobile || isiOSMobile;



      const notificationPayload: any = {
        type: Office.MailboxEnums.ItemNotificationMessageType.ErrorMessage,
        message: itemHasAttachments ? warningWithAttachments : warningWithoutAttachments,
      };

      // // Android/iOS platforms enforce strict key validations and expect "none"
      // if (isMobile) {
      //   // notificationPayload.persistent = false;
      //   // notificationPayload.icon = "inMailX_icon16";
      // }

      await new Promise<void>((resolve) => { mailItem.notificationMessages.replaceAsync("ExternalDomainWarning", notificationPayload, () => resolve()); });
    }
    else {
      // Remove the notification banner if all domains match or if the external user was removed
      await new Promise<void>((resolve) => { mailItem.notificationMessages.removeAsync("ExternalDomainWarning", () => resolve()); });
    }
  } catch (error) {
    console.error("Bypassed unexpected error in UI validation: ", error);
  }
}



async function OnMessageRecipientsChangedHandler(event: SafeRecipientsChangedEvent): Promise<void> {
  if (!event) return;

  try {
    const mailItem = Office.context.mailbox.item;

    if (mailItem == null || mailItem.itemType !== Office.MailboxEnums.ItemType.Message) {
      return;
    }

    // const itemHasAttachments = await selectedItemHasAttachments().catch(() => false);

    //Using safe fallback handling for Android
    const checkTo = event.changedRecipientFields ? !!event.changedRecipientFields.to : true;
    const checkCc = event.changedRecipientFields ? !!event.changedRecipientFields.cc : true;
    const checkBcc = event.changedRecipientFields ? !!event.changedRecipientFields.bcc : true;

    // Execute the shared validation logic
    await validateRecipientsAndShowNotification(mailItem, checkTo, checkCc, checkBcc);
  } catch (error) {
    console.error("Error processing recipient validation:", error);
  } finally {
    if (event && typeof event.completed === "function") {
      event.completed();
    }
  }
}

