async function OnMessageSendHandler(event: Office.AddinCommands.Event) {
  if (!event) return;

  try {
    // const mailItem = Office.context.mailbox.item;
    const mailItem: Office.MessageCompose = Office.context.mailbox.item as Office.MessageCompose;

    if (mailItem == null || mailItem.itemType !== Office.MailboxEnums.ItemType.Message) {
      return;
    }

    let hasExternalRecipient = false;
    const itemHasAttachments = await selectedItemHasAttachments().catch(() => false);

    const externalRecipientValidationResult: ExternalRecipientsValidationResult = getInvalidRecipients([...await getRecipientsWithTimeout(mailItem.to).catch(() => []), ...await getRecipientsWithTimeout(mailItem.cc).catch(() => []), ...await getRecipientsWithTimeout(mailItem.bcc).catch(() => [])]);


    if (externalRecipientValidationResult.HasExternalDomain) {

      const warningWithAttachments = "Verify that each recipient and attachment is correct before sending.";
      const warningWithoutAttachments = "Verify that each recipient is correct before sending.";

      //Office.SmartAlertsEventCompletedOptions
      const commandId = "messageSendGuard_1";

      if (itemHasAttachments) {
        // Show a prompt to the user before sending the email
        //const userConfirmed = confirm(warningWithAttachments);
        const completionOptions: Office.SmartAlertsEventCompletedOptions = {
          allowEvent: false,
          errorMessage: warningWithAttachments,
          errorMessageMarkdown: `The following recipients ${(externalRecipientValidationResult.ExternalRecipients.length > 1 ? "are" : "is")} external:\n\n ${externalRecipientValidationResult.ExternalRecipients.join(", ")}`,
          // cancelLabel: "Review Recipients",
          sendModeOverride: Office.MailboxEnums.SendModeOverride.PromptUser,
          // commandId: commandId
        };
        event.completed(completionOptions);
      }
      else {

        const completionOptions: Office.SmartAlertsEventCompletedOptions = {
          allowEvent: false,
          errorMessage: warningWithoutAttachments,
          errorMessageMarkdown: `The following recipients ${(externalRecipientValidationResult.ExternalRecipients.length > 1 ? "are" : "is")} external:\n\n ${externalRecipientValidationResult.ExternalRecipients.join(", ")}`,
          // cancelLabel: "Do not Send",
          sendModeOverride: Office.MailboxEnums.SendModeOverride.PromptUser,
          // commandId: commandId
        };
        event.completed(completionOptions);
      }
    }
    else {
      //no external recipients found, allow the send to proceed
      // event.completed({ allowEvent: true });

      const completionOptions: Office.SmartAlertsEventCompletedOptions = { allowEvent: true };
      event.completed(completionOptions);
    }
    return;
  } catch (error) {
    console.error("Error during message send handling:", error);
    event.completed();
  }
  // finally {
  //   if (event && typeof event.completed === "function") {
  //     event.completed();
  //   }
  // }
}






async function selectedItemHasAttachments(): Promise<boolean> {
  return new Promise<boolean>((resolve, reject) => {
    const item = Office.context.mailbox.item;
    if (!item) {
      reject(new Error("No item found in mailbox context."));
      return;
    }

    item.getAttachmentsAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {


        // resolve(result.value && result.value.length > 0);
        const hasRegularAttachment = result.value.some(attachment => !attachment.isInline);
        resolve(hasRegularAttachment);


      } else {
        reject(result.error);
      }
    });
  });
}

/**
 * FIXED: High-reliability wrapper for getAsync that self-rejects if Outlook stalls,
 * preventing the entire add-in background task container from being killed with a 5018 timeout error.
 */
function getRecipientsWithTimeout(recipientField: Office.Recipients): Promise<Office.EmailAddressDetails[]> {
  const apiCall = new Promise<Office.EmailAddressDetails[]>((resolve, reject) => {
    recipientField.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value || []);
      } else {
        reject(result.error);
      }
    });
  });

  // Self-destruct lookup execution if it stalls longer than 2.5 seconds
  const timeoutFallback = new Promise<Office.EmailAddressDetails[]>((_, reject) =>
    setTimeout(() => reject(new Error("Outlook API field lock timeout")), 2500)
  );

  return Promise.race([apiCall, timeoutFallback]);
}

function getRecipientsAsync(recipientField: Office.Recipients): Promise<Office.EmailAddressDetails[]> {
  return new Promise((resolve, reject) => {
    recipientField.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value);
      } else {
        reject(result.error);
      }
    });
  });
}

function hasInvalidDomain(recipients: Office.EmailAddressDetails[]): boolean {
  const domain = "@" + Office.context.mailbox.userProfile.emailAddress.split("@")[1].toLowerCase();
  return recipients.some((recipient) => {
    const email = recipient.emailAddress ? recipient.emailAddress.toLowerCase().trim() : "";
    return email.length > 0 && !email.endsWith(domain.toLowerCase());
  });
}

function getInvalidRecipients(recipients: Office.EmailAddressDetails[]): ExternalRecipientsValidationResult {
  const domain = "@" + Office.context.mailbox.userProfile.emailAddress.split("@")[1].toLowerCase();

  // const invalidRecipients = recipients.filter((recipient) => {
  //   const email = recipient.emailAddress ? recipient.emailAddress.toLowerCase().trim() : "";
  //   return email.length > 0 && !email.endsWith(domain.toLowerCase());
  // });

  const invalidRecipients = recipients.map(recipient => recipient.emailAddress ? recipient.emailAddress.toLowerCase().trim() : "").filter(email => email.length > 0 && !email.endsWith(domain));

  return {
    HasExternalDomain: invalidRecipients.length > 0,
    ExternalRecipients: invalidRecipients,
  };
}


async function checkOutgoingMessageForExternalRecipients(): Promise<boolean> {
  const mailItem = Office.context.mailbox.item;

  if (mailItem == null || mailItem.itemType !== Office.MailboxEnums.ItemType.Message) {
    return false;
  }

  const toRecipients = await getRecipientsWithTimeout(mailItem.to).catch(() => []);
  const ccRecipients = await getRecipientsWithTimeout(mailItem.cc).catch(() => []);
  const bccRecipients = await getRecipientsWithTimeout(mailItem.bcc).catch(() => []);

  const allRecipients = [...toRecipients, ...ccRecipients, ...bccRecipients];
  return hasInvalidDomain(allRecipients);
}


